def now_iso(): return datetime.now().isoformat(timespec="seconds")
def hash_password(p):
    salt=os.urandom(16); key=hashlib.pbkdf2_hmac("sha256",p.encode(),salt,120000); return base64.b64encode(salt+key).decode()
def check_password(p, stored):
    try:
        raw=base64.b64decode(str(stored).encode()); return hashlib.pbkdf2_hmac("sha256",p.encode(),raw[:16],120000)==raw[16:]
    except Exception: return False

def conn(): return sqlite3.connect(DB_PATH, check_same_thread=False)
def read_df(q, params=()):
    c=conn()
    try: return pd.read_sql_query(q,c,params=params)
    finally: c.close()
def exec_sql(q, params=()):
    c=conn(); cur=c.cursor(); cur.execute(q,params); c.commit(); lid=cur.lastrowid; c.close()
    q_upper=str(q).upper()
    tablas_excel=['PNC_REGISTROS','ME_REGISTROS','DDM_RX_REGISTROS','MUESTRAS_10_MESES','MUESTRAS_12_MESES_ALERGENO','MUESTRAS_12_MESES_DUVALIN','MUESTRAS_12_MESES_NAVE2','MUESTRAS_15_MESES','MUESTRAS_18_MESES','MUESTRAS_24_MESES']
    if any(t in q_upper for t in tablas_excel) and any(a in q_upper for a in ['INSERT','UPDATE','DELETE']):
        try: sync_excel_desde_db()
        except Exception as e: st.session_state['excel_sync_error']=str(e)
    return lid

def sync_excel_desde_db():
    """Replica las diez tablas operativas en un único libro, una hoja por tabla."""
    hojas={
        'PNC':'pnc_registros','Materia Extraña':'me_registros','Detector Metales RX':'ddm_rx_registros',
        '10 Meses':'muestras_10_meses','12 Meses Alérgeno':'muestras_12_meses_alergeno',
        '12 Meses Duvalin':'muestras_12_meses_duvalin','12 Meses Nave 2':'muestras_12_meses_nave2',
        '15 Meses':'muestras_15_meses','18 Meses':'muestras_18_meses','24 Meses':'muestras_24_meses'
    }
    with _EXCEL_LOCK:
        wb=load_workbook(EXCEL_PATH) if EXCEL_PATH.exists() else Workbook()
        if 'Sheet' in wb.sheetnames and len(wb.sheetnames)==1: wb.remove(wb['Sheet'])
        for nombre,tabla in hojas.items():
            df=read_df(f'SELECT * FROM {tabla} ORDER BY id ASC')
            ws=wb[nombre] if nombre in wb.sheetnames else wb.create_sheet(nombre)
            ws.delete_rows(1,ws.max_row)
            headers=list(df.columns)
            if not headers:
                # Obtiene encabezados aun cuando no existan registros.
                c=conn(); headers=[r[1] for r in c.execute(f'PRAGMA table_info({tabla})').fetchall()]; c.close()
            for col,h in enumerate(headers,1):
                cell=ws.cell(1,col,h); cell.font=Font(bold=True,color='FFFFFF'); cell.fill=PatternFill('solid',fgColor='062C36'); cell.alignment=Alignment(horizontal='center')
            for r_idx,row in enumerate(df.itertuples(index=False,name=None),2):
                for c_idx,value in enumerate(row,1): ws.cell(r_idx,c_idx,value)
            ws.freeze_panes='A2'; ws.auto_filter.ref=f'A1:{get_column_letter(max(1,len(headers)))}{max(1,ws.max_row)}'
            for i,h in enumerate(headers,1):
                max_len=max([len(str(h))]+[len(str(ws.cell(r,i).value or '')) for r in range(2,min(ws.max_row,200)+1)])
                ws.column_dimensions[get_column_letter(i)].width=min(max(max_len+2,12),45)
        wb.save(EXCEL_PATH)

def reset_autoincrement(table):
    try:
        df=read_df(f'SELECT COALESCE(MAX(id),0) AS max_id FROM {table}')
        max_id=int(df.iloc[0]['max_id']) if not df.empty else 0
        exec_sql('UPDATE sqlite_sequence SET seq=? WHERE name=?',(max_id,table))
    except Exception:
        pass

def opt_blank(values):
    return [''] + [str(v) for v in values if str(v).strip()]

def idx_or_zero(options, value):
    value='' if value is None else str(value)
    return options.index(value) if value in options else 0

def normalizar_catalogo(v):
    import unicodedata
    t=unicodedata.normalize('NFKD',str(v or '').strip().upper())
    return ' '.join(''.join(c for c in t if not unicodedata.combining(c)).split())

def nave_por_catalogo(linea,grupo=''):
    d=read_df('SELECT nave,linea_norm,sector_norm FROM catalogo_naves_lineas WHERE activo=1')
    for v in (normalizar_catalogo(linea),normalizar_catalogo(grupo)):
        if v and not d.empty:
            x=d[(d.linea_norm==v)|(d.sector_norm==v)]
            if not x.empty:return str(x.iloc[0].nave)
    return ''

def clasificar_filas(filas):
    t={'Nave 1':0.0,'Nave 2':0.0,'Nave 3':0.0,'Sin clasificar':0.0};out=[]
    for g,l,p,h,c,o,n in filas:
        nv=nave_por_catalogo(l,g) or 'Sin clasificar';t[nv]+=float(h or 0);out.append((g,l,p,h,c,o,n,nv))
    return t,out

def guardar_matriz(eid,fecha,analista,carga,tot):
    analista_limpio=str(analista or '').strip()
    exec_sql('INSERT INTO matriz_entrega(fecha,analista,entrega_id,total_carga_datos,horas_nave1,horas_nave2,horas_nave3,actualizado_en) VALUES(?,?,?,?,?,?,?,?)',(fecha,analista_limpio,eid,carga,tot.get('Nave 1',0),tot.get('Nave 2',0),tot.get('Nave 3',0),now_iso()))

def excel_matriz(df):
    b=BytesIO()
    with pd.ExcelWriter(b,engine='openpyxl') as w:
        base=df.rename(columns={'fecha':'Fecha','analista':'Analista','total_carga_datos':'Total carga de datos','horas_nave1':'Horas Nave 1','horas_nave2':'Horas Nave 2','horas_nave3':'Horas Nave 3'})
        base.to_excel(w,sheet_name='Base indicadores',index=False)
        for c,n in [('total_carga_datos','Total carga'),('horas_nave1','Horas Nave 1'),('horas_nave2','Horas Nave 2'),('horas_nave3','Horas Nave 3')]:df.pivot_table(index='analista',columns='fecha',values=c,aggfunc='sum',fill_value=0).to_excel(w,sheet_name=n)
        for ws in w.book.worksheets:
            ws.freeze_panes='A2'
            for cell in ws[1]:cell.font=Font(bold=True,color='FFFFFF');cell.fill=PatternFill('solid',fgColor='062C36')
    return b.getvalue()

def pdf_entrega(eid):
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4,landscape
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle
    except ModuleNotFoundError:return None
    h=read_df('SELECT * FROM entregas_turno WHERE id=?',(eid,));d=read_df('SELECT * FROM entregas_turno_lineas WHERE entrega_id=? ORDER BY orden_fila',(eid,));m=read_df('SELECT * FROM matriz_entrega WHERE entrega_id=?',(eid,))
    if h.empty:return None
    r=h.iloc[0];b=BytesIO();doc=SimpleDocTemplate(b,pagesize=landscape(A4),leftMargin=28,rightMargin=28,topMargin=28,bottomMargin=28);sty=getSampleStyleSheet();story=[Paragraph('REPORTE DE ENTREGA DE TURNO',sty['Title']),Spacer(1,8)]
    meta=[['Registro',eid,'Fecha',r.fecha,'Analista',r.analista,'Turno',r.turno],['Nave',r.nave,'Referencia',r.referencia,'Creado por',r.creado_por,'Creado en',r.creado_en]];t=Table(meta);t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.4,colors.grey),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#DDF4EF'))]));story+=[t,Spacer(1,10)]
    if not m.empty:
        x=m.iloc[0];mt=Table([['Total carga','Horas Nave 1','Horas Nave 2','Horas Nave 3'],[f'{x.total_carga_datos:.2f}',f'{x.horas_nave1:.2f}',f'{x.horas_nave2:.2f}',f'{x.horas_nave3:.2f}']],colWidths=[165]*4);mt.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#062C36')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ALIGN',(0,0),(-1,-1),'CENTER'),('GRID',(0,0),(-1,-1),.4,colors.grey)]));story+=[mt,Spacer(1,10)]
    data=[['Nave','Grupo','Línea/Sector','Producto/Análisis','Horas','Carga','Observaciones']]
    for q in d.itertuples():data.append([str(getattr(q,'nave_catalogo','') or ''),q.grupo or '',q.linea or '',q.producto_descripcion or '',f'{float(q.horas_trabajadas or 0):.2f}',f'{float(q.carga_spac or 0):.2f}',q.observaciones or ''])
    dt=Table(data,colWidths=[55,85,145,145,45,45,190],repeatRows=1);dt.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#0A4652')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTSIZE',(0,0),(-1,-1),7),('GRID',(0,0),(-1,-1),.3,colors.grey),('VALIGN',(0,0),(-1,-1),'MIDDLE')]));story.append(dt);doc.build(story);return b.getvalue()

def matriz_entregas():
    st.markdown('## Entregas de turno y matriz histórica')
    st.caption('Consulta los registros de las tres naves, descarga cualquier PDF y exporta la matriz del rango seleccionado.')
    df=read_df("SELECT m.id,m.fecha,m.analista,m.entrega_id,m.total_carga_datos,m.horas_nave1,m.horas_nave2,m.horas_nave3,COALESCE(e.nave,'') AS nave,COALESCE(e.turno,'') AS turno FROM matriz_entrega m LEFT JOIN entregas_turno e ON e.id=m.entrega_id ORDER BY m.fecha DESC,m.analista")
    if df.empty:
        st.info('Todavía no hay entregas de turno registradas.')
        return
    df['fecha_dt']=pd.to_datetime(df['fecha'],errors='coerce').dt.date
    validas=df['fecha_dt'].dropna()
    if validas.empty:
        st.warning('Los registros existentes no contienen fechas válidas.')
        return
    mn,mx=min(validas),max(validas)
    a,b,c=st.columns(3)
    desde=a.date_input('Fecha inicial',mn,min_value=mn,max_value=mx,key='mx_desde')
    hasta=b.date_input('Fecha final',mx,min_value=mn,max_value=mx,key='mx_hasta')
    naves=c.multiselect('Nave',['Nave 1','Nave 2','Nave 3'],key='mx_naves')
    if desde>hasta:
        st.error('La fecha inicial no puede ser posterior a la fecha final.')
        return
    nombres=sorted(df['analista'].dropna().astype(str).unique())
    analistas=st.multiselect('Analista',nombres,key='mx_names')
    f=df[(df['fecha_dt']>=desde)&(df['fecha_dt']<=hasta)].copy()
    if naves:f=f[f['nave'].isin(naves)]
    if analistas:f=f[f['analista'].isin(analistas)]
    if f.empty:
        st.info('No existen registros para los filtros seleccionados.')
        return
    vista=f[['id','entrega_id','fecha','nave','turno','analista','total_carga_datos','horas_nave1','horas_nave2','horas_nave3']].copy()
    vista['PDF']='Disponible'
    vista=vista.rename(columns={'id':'ID matriz','entrega_id':'Registro','fecha':'Fecha','nave':'Nave','turno':'Turno','analista':'Analista','total_carga_datos':'Total carga','horas_nave1':'Horas Nave 1','horas_nave2':'Horas Nave 2','horas_nave3':'Horas Nave 3'})
    nonce=st.session_state.get('mx_table_nonce',0)
    evento=st.dataframe(vista,use_container_width=True,hide_index=True,on_select='rerun',selection_mode='single-row',key=f'mx_table_{nonce}',column_config={'PDF':st.column_config.TextColumn('PDF del registro',help='Selecciona la fila para descargar el PDF.')})
    excel_df=f[['fecha','nave','turno','analista','total_carga_datos','horas_nave1','horas_nave2','horas_nave3']].copy()
    st.download_button('Descargar matriz en Excel',excel_matriz(excel_df),f'matriz_entregas_{desde}_{hasta}.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',key='mx_excel')
    rows=getattr(evento,'selection',{}).get('rows',[]) if evento is not None else []
    valida=bool(rows) and isinstance(rows[0],int) and 0<=rows[0]<len(vista)
    if valida:
        seleccion=vista.iloc[rows[0]]
        rid=int(seleccion['ID matriz'])
        coincidencia=f[f['id']==rid]
        if not coincidencia.empty:
            row=coincidencia.iloc[0]
            eid=int(row['entrega_id']) if pd.notna(row['entrega_id']) else None
            st.markdown(f"### Registro seleccionado: {eid or 'Sin número'} | {row['fecha']} | {row['nave']} | {row['analista']}")
            if eid:
                contenido_pdf=pdf_entrega(eid)
                if contenido_pdf:
                    st.download_button('Descargar PDF de este registro',contenido_pdf,f'entrega_turno_{eid}_{row["fecha"]}.pdf','application/pdf',key=f'mx_pdf_{rid}_{eid}')
                else:
                    st.warning('No fue posible generar el PDF. Verifica que reportlab esté incluido en requirements.txt.')
            else:
                st.warning('Este indicador no tiene una entrega de turno relacionada.')
            if st.button('Eliminar día seleccionado',key=f'mx_del_{rid}'):
                st.session_state.mx_confirm=rid
            if st.session_state.get('mx_confirm')==rid:
                st.warning('Se eliminará la matriz y toda la entrega de turno relacionada. Después podrás registrar nuevamente esa fecha.')
                x,y=st.columns(2)
                if x.button('Sí, eliminar definitivamente',key=f'mx_ok_{rid}'):
                    cdb=conn();cur=cdb.cursor()
                    try:
                        if eid:
                            cur.execute('DELETE FROM entregas_turno_seguimientos WHERE entrega_id=?',(eid,))
                            cur.execute('DELETE FROM entregas_turno_lineas WHERE entrega_id=?',(eid,))
                            cur.execute('DELETE FROM entregas_turno WHERE id=?',(eid,))
                        cur.execute('DELETE FROM matriz_entrega WHERE id=?',(rid,))
                        cdb.commit()
                    except Exception:
                        cdb.rollback();raise
                    finally:cdb.close()
                    audit(st.session_state.auth['usuario'],'ELIMINAR_DIA_MATRIZ',f'Matriz {rid} | Entrega {eid}')
                    st.session_state.pop('mx_confirm',None)
                    st.session_state.mx_table_nonce=nonce+1
                    st.rerun()
                if y.button('Cancelar',key=f'mx_cancel_{rid}'):
                    st.session_state.pop('mx_confirm',None)
                    st.session_state.mx_table_nonce=nonce+1
                    st.rerun()
    elif rows:
        st.session_state.mx_table_nonce=nonce+1
        st.rerun()
    st.markdown('### Matrices por fecha y analista')
    for campo,titulo in [('total_carga_datos','Total de carga de datos'),('horas_nave1','Horas trabajadas Nave 1'),('horas_nave2','Horas trabajadas Nave 2'),('horas_nave3','Horas trabajadas Nave 3')]:
        st.markdown(f'**{titulo}**')
        st.dataframe(f.pivot_table(index='analista',columns='fecha',values=campo,aggfunc='sum',fill_value=0),use_container_width=True)


def migrar_matriz_fecha_analista(cur):
    """Cambia la restricción anterior UNIQUE(fecha) por UNIQUE(fecha, analista)."""
    fila = cur.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name='matriz_entrega'").fetchone()
    sql_actual = (fila[0] if fila and fila[0] else '').replace(' ', '').replace('\n', '').upper()
    if not sql_actual or 'UNIQUE(FECHA,ANALISTA)' in sql_actual:
        return
    cur.execute('ALTER TABLE matriz_entrega RENAME TO matriz_entrega_anterior')
    cur.execute("""CREATE TABLE matriz_entrega(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        fecha TEXT NOT NULL,
        analista TEXT NOT NULL,
        entrega_id INTEGER,
        total_carga_datos REAL DEFAULT 0,
        horas_nave1 REAL DEFAULT 0,
        horas_nave2 REAL DEFAULT 0,
        horas_nave3 REAL DEFAULT 0,
        actualizado_en TEXT,
        UNIQUE(fecha,analista)
    )""")
    cur.execute("""INSERT OR IGNORE INTO matriz_entrega
        (id,fecha,analista,entrega_id,total_carga_datos,horas_nave1,horas_nave2,horas_nave3,actualizado_en)
        SELECT id,fecha,COALESCE(NULLIF(TRIM(analista),''),'SIN ANALISTA'),entrega_id,
               total_carga_datos,horas_nave1,horas_nave2,horas_nave3,actualizado_en
        FROM matriz_entrega_anterior""")
    cur.execute('DROP TABLE matriz_entrega_anterior')

def formato_entrega(nave,tipo='PROCESO'):
    df=read_df("SELECT linea,sector,tipo_analisis,orden_linea,orden_sector FROM catalogo_formatos_entrega WHERE formato_nave=? AND tipo=? AND activo=1 ORDER BY orden_linea,orden_sector,id",(nave,tipo))
    if tipo=='ANALISIS':
        return [(str(r.linea),str(r.sector),str(r.tipo_analisis or '')) for r in df.itertuples()]
    resultado={}
    for r in df.itertuples(): resultado.setdefault(str(r.linea),[]).append(str(r.sector))
    return resultado

def migrar_catalogo_formatos_entrega(cur):
    """Migra cualquier versión anterior sin perder los formatos existentes."""
    fila=cur.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name='catalogo_formatos_entrega'").fetchone()
    if not fila:
        cur.execute("CREATE TABLE catalogo_formatos_entrega(id INTEGER PRIMARY KEY AUTOINCREMENT,formato_nave TEXT NOT NULL,tipo TEXT NOT NULL,linea TEXT NOT NULL,sector TEXT NOT NULL,tipo_analisis TEXT DEFAULT '',orden_linea INTEGER DEFAULT 0,orden_sector INTEGER DEFAULT 0,activo INTEGER DEFAULT 1,UNIQUE(formato_nave,tipo,linea,sector,tipo_analisis))")
        return
    columnas={r[1] for r in cur.execute('PRAGMA table_info(catalogo_formatos_entrega)').fetchall()}
    requeridas={'id','formato_nave','tipo','linea','sector','tipo_analisis','orden_linea','orden_sector','activo'}
    if requeridas.issubset(columnas):
        return
    cur.execute('ALTER TABLE catalogo_formatos_entrega RENAME TO catalogo_formatos_entrega_anterior')
    cur.execute("CREATE TABLE catalogo_formatos_entrega(id INTEGER PRIMARY KEY AUTOINCREMENT,formato_nave TEXT NOT NULL,tipo TEXT NOT NULL,linea TEXT NOT NULL,sector TEXT NOT NULL,tipo_analisis TEXT DEFAULT '',orden_linea INTEGER DEFAULT 0,orden_sector INTEGER DEFAULT 0,activo INTEGER DEFAULT 1,UNIQUE(formato_nave,tipo,linea,sector,tipo_analisis))")
    anteriores={r[1] for r in cur.execute('PRAGMA table_info(catalogo_formatos_entrega_anterior)').fetchall()}
    # Versión antigua: grupo representaba Línea y linea representaba Sector.
    if 'grupo' in anteriores:
        expr_linea="CASE WHEN TRIM(COALESCE(grupo,''))='MD - Car. Duros - FABRIMA' THEN 'FABRIMA' WHEN TRIM(COALESCE(grupo,''))='CAVE1000 / MOLDEO' THEN 'CV1000' ELSE TRIM(COALESCE(grupo,'')) END"
        expr_sector="TRIM(COALESCE(linea,''))"
        expr_orden_linea='COALESCE(orden_grupo,0)' if 'orden_grupo' in anteriores else '0'
        expr_orden_sector='COALESCE(orden_linea,0)' if 'orden_linea' in anteriores else '0'
    else:
        expr_linea="TRIM(COALESCE(linea,''))" if 'linea' in anteriores else "''"
        expr_sector="TRIM(COALESCE(sector,''))" if 'sector' in anteriores else expr_linea
        expr_orden_linea='COALESCE(orden_linea,0)' if 'orden_linea' in anteriores else '0'
        expr_orden_sector='COALESCE(orden_sector,0)' if 'orden_sector' in anteriores else '0'
    expr_tipo="COALESCE(NULLIF(TRIM(tipo),''),'PROCESO')" if 'tipo' in anteriores else "'PROCESO'"
    expr_analisis="COALESCE(tipo_analisis,'')" if 'tipo_analisis' in anteriores else "''"
    expr_activo='COALESCE(activo,1)' if 'activo' in anteriores else '1'
    expr_nave="TRIM(COALESCE(formato_nave,''))" if 'formato_nave' in anteriores else "''"
    expr_id='id' if 'id' in anteriores else 'NULL'
    cur.execute(f"""INSERT OR IGNORE INTO catalogo_formatos_entrega
        (id,formato_nave,tipo,linea,sector,tipo_analisis,orden_linea,orden_sector,activo)
        SELECT {expr_id},{expr_nave},{expr_tipo},{expr_linea},{expr_sector},{expr_analisis},
               {expr_orden_linea},{expr_orden_sector},{expr_activo}
        FROM catalogo_formatos_entrega_anterior
        WHERE {expr_nave}<>'' AND {expr_linea}<>'' AND {expr_sector}<>''""")
    cur.execute('DROP TABLE catalogo_formatos_entrega_anterior')
    # Fuerza la revisión de semillas para completar formatos faltantes sin duplicar los existentes.
    cur.execute("DELETE FROM app_config WHERE clave='formatos_entrega_linea_sector_v2'")

def asegurar_columnas_catalogos(cur):
    """Completa esquemas antiguos antes de insertar o consultar catálogos."""
    migraciones={
        'productos':{
            'item':'TEXT','descripcion':'TEXT','cliente':'TEXT',
            'familia':'TEXT','activo':'INTEGER DEFAULT 1'
        },
        'defectos':{
            'codigo':'TEXT','defecto':'TEXT','tipo_defecto':'TEXT',
            'clasificacion':'TEXT','activo':'INTEGER DEFAULT 1'
        },
        'catalogos':{
            'categoria':'TEXT','valor':'TEXT','activo':'INTEGER DEFAULT 1'
        },
        'catalogo_naves_lineas':{
            'nave':'TEXT','linea':'TEXT','sector':'TEXT',
            'linea_norm':'TEXT','sector_norm':'TEXT',
            'orden':'INTEGER DEFAULT 0','activo':'INTEGER DEFAULT 1'
        }
    }
    for tabla,columnas in migraciones.items():
        existe=cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",(tabla,)).fetchone()
        if not existe:
            continue
        actuales={r[1] for r in cur.execute(f'PRAGMA table_info({tabla})').fetchall()}
        for columna,tipo_sql in columnas.items():
            if columna not in actuales:
                cur.execute(f'ALTER TABLE {tabla} ADD COLUMN {columna} {tipo_sql}')
    # Normaliza nulos de bases anteriores.
    cur.execute('UPDATE productos SET activo=1 WHERE activo IS NULL')
    cur.execute('UPDATE defectos SET activo=1 WHERE activo IS NULL')
    cur.execute('UPDATE catalogos SET activo=1 WHERE activo IS NULL')
    cur.execute('UPDATE catalogo_naves_lineas SET activo=1 WHERE activo IS NULL')
    cur.execute("UPDATE catalogo_naves_lineas SET linea_norm=UPPER(TRIM(COALESCE(linea,''))) WHERE linea_norm IS NULL OR TRIM(linea_norm)='' ")
    cur.execute("UPDATE catalogo_naves_lineas SET sector_norm=UPPER(TRIM(COALESCE(sector,''))) WHERE sector_norm IS NULL OR TRIM(sector_norm)='' ")

def normalizar_formato_entrega_nave3(cur):
    """Separa TROQUEL DE POOSH y ENVASADO como lineas independientes."""
    existe = cur.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='catalogo_formatos_entrega'"
    ).fetchone()
    if not existe:
        return

    columnas = {
        fila[1]
        for fila in cur.execute(
            'PRAGMA table_info(catalogo_formatos_entrega)'
        ).fetchall()
    }
    necesarias = {'formato_nave', 'tipo', 'linea', 'sector', 'activo'}
    if not necesarias.issubset(columnas):
        return

    # TROQUEL DE POOSH permanece como una linea con un unico sector.
    cur.execute("""
        UPDATE catalogo_formatos_entrega
        SET linea='TROQUEL DE POOSH',
            sector='TROQUEL DE POOSH'
        WHERE formato_nave='Nave 3'
          AND tipo='PROCESO'
          AND activo=1
          AND UPPER(TRIM(linea))='TROQUEL DE POOSH'
          AND UPPER(TRIM(sector))='TROQUEL DE POOSH'
    """)

    # Los sectores de envasado que estaban agrupados bajo TROQUEL DE POOSH
    # se trasladan a la linea ENVASADO.
    sectores_envasado = {
        'ENVASADO HIGH DREAM': 'HIGH DREAM',
        'HIGH DREAM': 'HIGH DREAM',
        'ENVASADO VITROLEROS C2': 'ENVASADO VITROLEROS C2',
        'ENVASADO   VITROLEROS C2': 'ENVASADO VITROLEROS C2',
        'PFM': 'PFM',
        'PFM MULTIFORMATO': 'PFM Multiformato',
        'FLOW PACK BOSCH': 'Flow Pack Bosch',
        'YAMATO DE POOSH': 'Yamato de Poosh',
        'ENCAJILLADO GD´S': 'Encajillado GD´s',
        'EENCAJILLADO GD´S': 'Encajillado GD´s',
        'MBP 700': 'MBP 700'
    }

    for sector_anterior, sector_nuevo in sectores_envasado.items():
        filas = cur.execute("""
            SELECT id, orden_linea, orden_sector
            FROM catalogo_formatos_entrega
            WHERE formato_nave='Nave 3'
              AND tipo='PROCESO'
              AND activo=1
              AND UPPER(TRIM(linea))='TROQUEL DE POOSH'
              AND UPPER(TRIM(sector))=?
        """, (sector_anterior,)).fetchall()

        for registro_id, orden_linea, orden_sector in filas:
            duplicado = cur.execute("""
                SELECT id
                FROM catalogo_formatos_entrega
                WHERE formato_nave='Nave 3'
                  AND tipo='PROCESO'
                  AND activo=1
                  AND UPPER(TRIM(linea))='ENVASADO'
                  AND UPPER(TRIM(sector))=UPPER(TRIM(?))
                  AND id<>?
                LIMIT 1
            """, (sector_nuevo, registro_id)).fetchone()

            if duplicado:
                cur.execute(
                    'UPDATE catalogo_formatos_entrega SET activo=0 WHERE id=?',
                    (registro_id,)
                )
            else:
                cur.execute("""
                    UPDATE catalogo_formatos_entrega
                    SET linea='ENVASADO',
                        sector=?,
                        orden_linea=7,
                        orden_sector=COALESCE(orden_sector, 0)
                    WHERE id=?
                """, (sector_nuevo, registro_id))

    # Garantiza que el sector unico de TROQUEL DE POOSH exista.
    troquel = cur.execute("""
        SELECT id
        FROM catalogo_formatos_entrega
        WHERE formato_nave='Nave 3'
          AND tipo='PROCESO'
          AND UPPER(TRIM(linea))='TROQUEL DE POOSH'
          AND UPPER(TRIM(sector))='TROQUEL DE POOSH'
        LIMIT 1
    """).fetchone()

    if not troquel:
        cur.execute("""
            INSERT OR IGNORE INTO catalogo_formatos_entrega(
                formato_nave, tipo, linea, sector, tipo_analisis,
                orden_linea, orden_sector, activo
            ) VALUES('Nave 3','PROCESO','TROQUEL DE POOSH',
                     'TROQUEL DE POOSH','',6,0,1)
        """)

def init_db():
    UPLOAD_DIR.mkdir(exist_ok=True)
    c=conn(); cur=c.cursor()
    cur.execute("CREATE TABLE IF NOT EXISTS usuarios(id INTEGER PRIMARY KEY AUTOINCREMENT, usuario TEXT UNIQUE, nombre TEXT, password_hash TEXT, rol TEXT, activo INTEGER DEFAULT 1, creado_en TEXT)")
    cur.execute("CREATE TABLE IF NOT EXISTS app_config(clave TEXT PRIMARY KEY,valor TEXT,actualizado_en TEXT)")
